// ============================================================
// LORUV ORTAM İZLEME SİSTEMİ
// MERKEZİ AYARLAR + MEVSİMSEL KONTROL PLANI
// ============================================================
//
// Bu node bütün workflow'un merkezi yapılandırma noktasıdır.
//
// Buradan yönetilecekler:
//
// - Loruv Climate Bridge API
// - Ev ve Çatı sensörleri
// - Yaz / kış kontrol saatleri
// - Normal kontrol periyodu
// - Günlük sağlık raporu
// - HTTP / BLE retry davranışı
// - Telegram alarm tekrar süreleri
// - Hysteresis
// - Sensör RSSI / pil sağlığı
// - Evdeki elektronik cihazlar
// - Çatıdaki elektronik cihazlar
// - Ortak güvenli sıcaklık/nem aralıkları
// - Warning eşikleri
// - Çiğ noktası / yoğuşma riski
//
// ÖNEMLİ:
// Cihazların marka/model datasheet'leri elimizde olmadığı için
// aşağıdaki ekipman çalışma aralıkları GEÇİCİ ve muhafazakar
// genel varsayımlardır.
//
// İleride gerçek üretici değerleri bulunduğunda sadece bu
// node içindeki equipment değerlerini değiştirmek yeterlidir.
// ============================================================



// ============================================================
// 1. MERKEZİ CONFIG
// ============================================================

const CONFIG = {

    // ========================================================
    // SİSTEM
    // ========================================================

    system: {

        name:
            "Loruv Ortam İzleme Sistemi",

        timezone:
            "Europe/Istanbul",

    },


    // ========================================================
    // LORUV CLIMATE BRIDGE API
    // ========================================================

    api: {

        // Raspberry Pi IP adresini değiştir.
        //
        // Örnek:
        // http://RASPBERRY_PI_IP:8765

        baseUrl:
            "http://RASPBERRY_PI_IP:8765",


        // İki sensörü tek API isteğinde alacağız.
        //
        // Böylece Ev ve Çatı için ayrı BLE taraması yapılmaz.

        endpoint:
            "/api/v1/lywsd03mmc-devices",


        // Tüm BLE scan + GATT okumaları bazen uzun sürebilir.
        // Bu değer HTTP Request node'unda kullanılacak.

        timeoutMs:
            120000,


        // Sensörün read_at değeri bundan daha eskiyse
        // stale / geçersiz veri kabul edeceğiz.

        maxDataAgeMinutes:
            15,

    },


    // ========================================================
    // 2. SENSÖRLER
    // ========================================================

    sensors: {

        home: {

            zoneKey:
                "home",

            name:
                "Ev",

            deviceId:
                "lywsd03mmc-home-example",

        },


        attic: {

            zoneKey:
                "attic",

            name:
                "Çatı",

            deviceId:
                "lywsd03mmc-attic-example",

        },

    },


    // ========================================================
    // 3. MEVSİMSEL KONTROL PLANI
    // ========================================================

    schedule: {

        // ----------------------------------------------------
        // YAZ
        // ----------------------------------------------------
        //
        // Haziran - Temmuz - Ağustos - Eylül
        //

        summerMonths: [
            6,
            7,
            8,
            9,
        ],


        // Yazın günün sıcak döneminde her saat kontrol.
        //
        // Schedule Trigger :05'te çalıştığı için:
        //
        // 12:05
        // 13:05
        // ...
        // 19:05
        //

        summerPriorityHours: [
            12,
            13,
            14,
            15,
            16,
            17,
            18,
            19,
        ],


        // ----------------------------------------------------
        // KIŞ
        // ----------------------------------------------------
        //
        // Kasım - Aralık - Ocak - Şubat - Mart
        //

        winterMonths: [
            11,
            12,
            1,
            2,
            3,
        ],


        // Kışın en soğuk olması beklenen gece sonu /
        // sabah erken saatlerinde her saat kontrol.

        winterPriorityHours: [
            3,
            4,
            5,
            6,
            7,
            8,
            9,
        ],


        // ----------------------------------------------------
        // GEÇİŞ AYLARI
        // ----------------------------------------------------

        transitionMonths: [
            4,
            5,
            10,
        ],


        // ----------------------------------------------------
        // NORMAL KONTROL
        // ----------------------------------------------------
        //
        // Öncelikli saatlerin dışında 3 saatte bir.
        //
        // Varsayılan:
        //
        // 00:05
        // 03:05
        // 06:05
        // 09:05
        // 12:05
        // 15:05
        // 18:05
        // 21:05
        //

        normalIntervalHours:
            3,


        // ----------------------------------------------------
        // GÜNLÜK SAĞLIK RAPORU
        // ----------------------------------------------------

        dailyReportHour:
            9,

    },


// ========================================================
// 4. RETRY AYARLARI
// ========================================================

    retry: {

        // HTTP Request node'u bağlantı / HTTP hatasında
        // toplam iki kez deneyecek.
        httpMaxAttempts: 2,

        // n8n HTTP Request node'unda izin verilen
        // maksimum retry bekleme süresi.
        httpWaitSeconds: 5,

        // HTTP isteği başarılı olsa bile sensörlerden biri
        // BLE/GATT üzerinden okunamamış olabilir.
        //
        // Climate Bridge API'nin RAM cache'i 60 saniye olduğu
        // için ikinci sensör okumasından önce 70 saniye bekliyoruz.
        //
        // Böylece ikinci istek eski hatalı cache'i değil,
        // yeni bir BLE taraması ve cihaz okumasını tetikler.
        sensorRetryWaitSeconds: 70,

        // İlk okumanın ardından yalnızca bir kez
        // sensör-seviyesi tekrar denemesi yapılacak.
        sensorRetryAttempts: 1,

    },


    // ========================================================
    // 5. ALARM DAVRANIŞI
    // ========================================================

    alerts: {

        // Warning devam ederse tekrar mesaj süresi.

        warningRepeatMinutes:
            180,


        // Kritik durum devam ederse tekrar mesaj süresi.

        criticalRepeatMinutes:
            60,


        // API / BLE / sensör okunamıyorsa tekrar hata mesajı.

        dataFailureRepeatMinutes:
            180,


        // Veri tekrar gelmeye başladığında mesaj gönder.

        sendDataRecovery:
            true,


        // Ortam tekrar normale döndüğünde mesaj gönder.

        sendEnvironmentRecovery:
            true,


        // Her gün sistem sağlık raporu gönder.

        sendDailyHealthReport:
            true,

    },


    // ========================================================
    // 6. WARNING MARJLARI
    // ========================================================
    //
    // Cihazların ortak kritik aralığı aşağıda otomatik
    // hesaplanacak.
    //
    // Warning seviyesi ise kritik sınıra yaklaşmadan önce
    // oluşturulacak.
    //
    // Örneğin:
    //
    // tempMax = 40
    // tempUpperMargin = 5
    //
    // warningMax = 35 °C
    //
    // ========================================================

    warningMargins: {

        temperatureUpperC:
            5,

        temperatureLowerC:
            3,

        humidityUpperPercent:
            5,

        humidityLowerPercent:
            5,

    },


    // ========================================================
    // 7. HYSTERESIS
    // ========================================================
    //
    // Alarm sınırında sürekli gidip gelen değerlerin:
    //
    // KRİTİK
    // NORMAL
    // KRİTİK
    // NORMAL
    //
    // mesajı oluşturmasını engeller.
    //
    // Örneğin:
    //
    // kritik = 40 °C
    // hysteresis = 2 °C
    //
    // 40.1 → kritik
    //
    // ancak sıcaklık yaklaşık 38 °C seviyesine dönmeden
    // recovery vermeyebiliriz.
    //
    // ========================================================

    hysteresis: {

        temperatureC:
            2,

        humidityPercent:
            5,

    },


    // ========================================================
    // 8. ÇİĞ NOKTASI / YOĞUŞMA RİSKİ
    // ========================================================
    //
    // Daha sonraki alarm node'unda sıcaklık + bağıl nem
    // kullanılarak dew point hesaplanacak.
    //
    // Asıl faydalı metrik:
    //
    // ortam sıcaklığı - dew point
    //
    // farkıdır.
    //
    // Fark küçüldükçe yoğuşma ihtimali artar.
    //
    // Bu sensör cihaz yüzey sıcaklığını ölçmediği için bu
    // değer kesin "yoğuşma var" anlamına gelmez.
    //
    // Risk göstergesi olarak kullanılacaktır.
    //
    // ========================================================

    condensation: {

        enabled:
            true,


        // 4 °C veya daha az fark:
        //
        // Yoğuşma açısından dikkat.

        warningSpreadC:
            4,


        // 2 °C veya daha az fark:
        //
        // Yüksek yoğuşma riski.

        criticalSpreadC:
            2,

    },


    // ========================================================
    // 9. SENSÖR SAĞLIĞI
    // ========================================================

    sensorHealth: {

        // RSSI bu değerden daha düşükse sinyal zayıf kabul edilir.
        //
        // Örnek:
        //
        // -60 iyi
        // -80 zayıflamaya başladı
        // -90 çok zayıf

        weakSignalDbm:
            -90,


        // Kritik sinyal seviyesi.
        //
        // Bu değer civarında BLE bağlantı başarısızlıkları
        // daha olası hale gelebilir.

        criticalSignalDbm:
            -100,


        // LYWSD03MMC stock firmware pil yüzdesi güvenilir
        // olmayabileceğinden esas olarak voltajı izleyeceğiz.
        //
        // Şimdilik gerçek cihaz davranışı hakkında yeterli
        // veri biriktirmediğimiz için otomatik voltaj alarmını
        // kapalı bırakıyoruz.

        batteryWarningVoltage:
            null,

        batteryCriticalVoltage:
            null,

    },


    // ========================================================
    // 10. BÖLGELER VE EKİPMANLAR
    // ========================================================

    zones: {


        // ====================================================
        // EV
        // ====================================================

        home: {

            name:
                "Ev",


            // Bu değerlerin datasheet değil, genel muhafazakâr
            // başlangıç değerleri olduğunu açıkça tutuyoruz.

            limitsAreAssumptions:
                true,


            equipment: [


                // --------------------------------------------
                // Raspberry Pi
                // --------------------------------------------
                //
                // Burada CPU sıcaklığını değil Raspberry Pi'nin
                // bulunduğu ORTAMI izliyoruz.
                //

                {
                    name:
                        "Raspberry Pi",

                    tempMin:
                        0,

                    tempMax:
                        50,

                    humidityMin:
                        10,

                    humidityMax:
                        80,
                },


                // --------------------------------------------
                // SSD
                // --------------------------------------------

                {
                    name:
                        "SSD",

                    tempMin:
                        0,

                    tempMax:
                        50,

                    humidityMin:
                        10,

                    humidityMax:
                        80,
                },


                // --------------------------------------------
                // Modem / Router
                // --------------------------------------------

                {
                    name:
                        "Modem",

                    tempMin:
                        0,

                    tempMax:
                        40,

                    humidityMin:
                        10,

                    humidityMax:
                        80,
                },


                // --------------------------------------------
                // LCD TV
                // --------------------------------------------

                {
                    name:
                        "LCD TV",

                    tempMin:
                        0,

                    tempMax:
                        40,

                    humidityMin:
                        20,

                    humidityMax:
                        80,
                },


                // --------------------------------------------
                // Robot Süpürge + Şarj İstasyonu
                // --------------------------------------------
                //
                // Batarya / şarj sistemi nedeniyle alt sıcaklık
                // tarafında biraz daha muhafazakâr davranıyoruz.
                //

                {
                    name:
                        "Robot Süpürge",

                    tempMin:
                        5,

                    tempMax:
                        40,

                    humidityMin:
                        10,

                    humidityMax:
                        80,
                },


                // --------------------------------------------
                // Akım Korumalı Priz
                // --------------------------------------------

                {
                    name:
                        "Akım Korumalı Priz",

                    tempMin:
                        0,

                    tempMax:
                        40,

                    humidityMin:
                        10,

                    humidityMax:
                        80,
                },

            ],

        },


        // ====================================================
        // ÇATI
        // ====================================================

        attic: {

            name:
                "Çatı",

            limitsAreAssumptions:
                true,


            equipment: [


                // --------------------------------------------
                // DVR
                // --------------------------------------------

                {
                    name:
                        "DVR",

                    tempMin:
                        0,

                    tempMax:
                        50,

                    humidityMin:
                        10,

                    humidityMax:
                        80,
                },


                // --------------------------------------------
                // 12V Güç Adaptörleri
                // --------------------------------------------
                //
                // Çatıdaki sistem için özellikle önemli.
                //
                // Ortam 40 °C olduğunda adaptör içindeki güç
                // elektroniği doğal olarak daha sıcak olabilir.
                //
                // Model bilinmediği için 40 °C çevre sıcaklığını
                // muhafazakâr geçici sınır kabul ediyoruz.
                //

                {
                    name:
                        "12V Güç Adaptörleri",

                    tempMin:
                        0,

                    tempMax:
                        40,

                    humidityMin:
                        10,

                    humidityMax:
                        80,
                },


                // --------------------------------------------
                // CCTV / Mikrofon / Ses Ekipmanları
                // --------------------------------------------

                {
                    name:
                        "CCTV / Ses Ekipmanları",

                    tempMin:
                        0,

                    tempMax:
                        45,

                    humidityMin:
                        10,

                    humidityMax:
                        80,
                },

            ],

        },

    },

};



// ============================================================
// 11. YARDIMCI FONKSİYON
// GEÇERLİ SAYISAL DEĞERLERİ AL
// ============================================================

function getFiniteValues(
    equipment,
    property
) {

    return equipment

        .map(
            item =>
                item[property]
        )

        .filter(
            value =>
                typeof value === "number" &&
                Number.isFinite(value)
        );

}



// ============================================================
// 12. BÖLGENİN ORTAK GÜVENLİ ÇALIŞMA ARALIĞINI HESAPLA
// ============================================================
//
// Örnek:
//
// DVR       0–50
// Adaptör   0–40
// CCTV      0–45
//
// Ortak:
// 0–40 °C
//
// Çünkü sistemdeki en hassas cihaz belirleyici olur.
// ============================================================

function calculateZoneLimits(
    zone,
    warningMargins
) {

    const equipment =
        zone.equipment;


    const tempMins =
        getFiniteValues(
            equipment,
            "tempMin"
        );


    const tempMaxs =
        getFiniteValues(
            equipment,
            "tempMax"
        );


    const humidityMins =
        getFiniteValues(
            equipment,
            "humidityMin"
        );


    const humidityMaxs =
        getFiniteValues(
            equipment,
            "humidityMax"
        );


    // --------------------------------------------------------
    // ORTAK KRİTİK SINIRLAR
    // --------------------------------------------------------

    const tempMin =
        tempMins.length > 0
            ? Math.max(...tempMins)
            : null;


    const tempMax =
        tempMaxs.length > 0
            ? Math.min(...tempMaxs)
            : null;


    const humidityMin =
        humidityMins.length > 0
            ? Math.max(...humidityMins)
            : null;


    const humidityMax =
        humidityMaxs.length > 0
            ? Math.min(...humidityMaxs)
            : null;


    // --------------------------------------------------------
    // HANGİ CİHAZ SINIRI BELİRLİYOR?
    // --------------------------------------------------------

    const tempMinDevices =
        equipment
            .filter(
                item =>
                    item.tempMin === tempMin
            )
            .map(
                item =>
                    item.name
            );


    const tempMaxDevices =
        equipment
            .filter(
                item =>
                    item.tempMax === tempMax
            )
            .map(
                item =>
                    item.name
            );


    const humidityMinDevices =
        equipment
            .filter(
                item =>
                    item.humidityMin === humidityMin
            )
            .map(
                item =>
                    item.name
            );


    const humidityMaxDevices =
        equipment
            .filter(
                item =>
                    item.humidityMax === humidityMax
            )
            .map(
                item =>
                    item.name
            );


    // --------------------------------------------------------
    // WARNING EŞİKLERİ
    // --------------------------------------------------------

    const warningTempMin =
        tempMin !== null
            ? tempMin +
                warningMargins.temperatureLowerC
            : null;


    const warningTempMax =
        tempMax !== null
            ? tempMax -
                warningMargins.temperatureUpperC
            : null;


    const warningHumidityMin =
        humidityMin !== null
            ? humidityMin +
                warningMargins.humidityLowerPercent
            : null;


    const warningHumidityMax =
        humidityMax !== null
            ? humidityMax -
                warningMargins.humidityUpperPercent
            : null;


    return {

        // Kritik sınırlar.

        critical: {

            temperature: {
                min:
                    tempMin,

                max:
                    tempMax,
            },

            humidity: {
                min:
                    humidityMin,

                max:
                    humidityMax,
            },

        },


        // Warning sınırları.

        warning: {

            temperature: {
                min:
                    warningTempMin,

                max:
                    warningTempMax,
            },

            humidity: {
                min:
                    warningHumidityMin,

                max:
                    warningHumidityMax,
            },

        },


        // Hangi cihaz(lar) ortak limiti belirledi?

        limitingEquipment: {

            temperatureMin:
                tempMinDevices,

            temperatureMax:
                tempMaxDevices,

            humidityMin:
                humidityMinDevices,

            humidityMax:
                humidityMaxDevices,

        },

    };

}



// ============================================================
// 13. TÜM BÖLGELERİN EFEKTİF LİMİTLERİNİ HESAPLA
// ============================================================

const zoneLimits = {};


for (
    const [zoneKey, zone]
    of Object.entries(CONFIG.zones)
) {

    zoneLimits[zoneKey] =
        calculateZoneLimits(
            zone,
            CONFIG.warningMargins
        );

}



// ============================================================
// 14. TÜRKİYE YEREL TARİH / SAATİ
// ============================================================
//
// n8n container'ın işletim sistemi timezone'una bağımlı
// kalmamak için timezone'u açıkça belirliyoruz.
// ============================================================

function getLocalDateParts(
    date,
    timezone
) {

    const formatter =
        new Intl.DateTimeFormat(
            "en-GB",
            {

                timeZone:
                    timezone,

                year:
                    "numeric",

                month:
                    "numeric",

                day:
                    "numeric",

                hour:
                    "numeric",

                minute:
                    "numeric",

                second:
                    "numeric",

                hourCycle:
                    "h23",

            }
        );


    const parts =
        formatter.formatToParts(
            date
        );


    const result = {};


    for (
        const part
        of parts
    ) {

        if (
            part.type === "literal"
        ) {

            continue;

        }


        result[
            part.type
        ] =
            Number(
                part.value
            );

    }


    return result;

}



const now =
    new Date();


const local =
    getLocalDateParts(
        now,
        CONFIG.system.timezone
    );


const month =
    local.month;


const hour =
    local.hour;



// ============================================================
// 15. MEVSİMİ BELİRLE
// ============================================================

let season =
    "transition";


if (
    CONFIG.schedule
        .summerMonths
        .includes(month)
) {

    season =
        "summer";

}

else if (
    CONFIG.schedule
        .winterMonths
        .includes(month)
) {

    season =
        "winter";

}



// ============================================================
// 16. ÖNCELİKLİ SAAT Mİ?
// ============================================================

let priorityWindow =
    false;


let scheduleReason =
    null;



// ------------------------------------------------------------
// YAZIN SICAK SAAT
// ------------------------------------------------------------

if (
    season === "summer" &&
    CONFIG.schedule
        .summerPriorityHours
        .includes(hour)
) {

    priorityWindow =
        true;


    scheduleReason =
        "summer_hot_hour";

}



// ------------------------------------------------------------
// KIŞIN SOĞUK SAAT
// ------------------------------------------------------------

else if (
    season === "winter" &&
    CONFIG.schedule
        .winterPriorityHours
        .includes(hour)
) {

    priorityWindow =
        true;


    scheduleReason =
        "winter_cold_hour";

}



// ============================================================
// 17. NORMAL 3 SAATLİK KONTROL
// ============================================================

const normalIntervalDue =
    (
        hour %
        CONFIG.schedule.normalIntervalHours
    ) === 0;



// ============================================================
// 18. SENSÖR OKUNACAK MI?
// ============================================================

const scheduledCheck =
    priorityWindow ||
    normalIntervalDue;


if (
    !scheduleReason &&
    normalIntervalDue
) {

    scheduleReason =
        "normal_interval";

}



// ============================================================
// 19. GÜNLÜK SAĞLIK RAPORU
// ============================================================

const isDailyReportTime =
    (
        hour ===
        CONFIG.schedule.dailyReportHour
    );



// Günlük rapor saati normal program dışında olsa bile
// sensörlerin okunmasını garanti ediyoruz.

const shouldCheck =
    scheduledCheck ||
    (
        CONFIG.alerts
            .sendDailyHealthReport &&
        isDailyReportTime
    );



// ============================================================
// 20. İNSAN TARAFINDAN OKUNABİLİR KONTROL AÇIKLAMASI
// ============================================================

let scheduleDescription =
    "Bu saatte sensör kontrolü gerekmiyor";


if (
    scheduleReason ===
    "summer_hot_hour"
) {

    scheduleDescription =
        "Yaz - sıcak saat kontrolü";

}


else if (
    scheduleReason ===
    "winter_cold_hour"
) {

    scheduleDescription =
        "Kış - soğuk saat kontrolü";

}


else if (
    scheduleReason ===
    "normal_interval"
) {

    scheduleDescription =
        `Normal ${CONFIG.schedule.normalIntervalHours} saatlik kontrol`;

}


if (
    isDailyReportTime
) {

    scheduleDescription +=
        " + günlük sağlık raporu";

}



// ============================================================
// 21. OUTPUT
// ============================================================

return [
    {
        json: {

            // ------------------------------------------------
            // SONRAKİ IF NODE
            // ------------------------------------------------

            shouldCheck,


            // ------------------------------------------------
            // GÜNLÜK RAPOR
            // ------------------------------------------------

            isDailyReportTime,


            // ------------------------------------------------
            // ZAMANLAMA
            // ------------------------------------------------

            season,

            priorityWindow,

            scheduleReason,

            scheduleDescription,


            // ------------------------------------------------
            // TÜRKİYE YEREL SAATİ
            // ------------------------------------------------

            localTime: {

                year:
                    local.year,

                month:
                    local.month,

                day:
                    local.day,

                hour:
                    local.hour,

                minute:
                    local.minute,

                second:
                    local.second,

            },


            // ------------------------------------------------
            // OTOMATİK HESAPLANAN BÖLGE LİMİTLERİ
            // ------------------------------------------------

            zoneLimits,


            // ------------------------------------------------
            // TÜM MERKEZİ AYARLAR
            // ------------------------------------------------

            config:
                CONFIG,

        },
    },
];

// ============================================================
// LORUV ORTAM İZLEME SİSTEMİ
// SENSÖR VERİLERİNİ AYIR + DOĞRULA + HAZIRLA
// ============================================================
//
// Bu node alarm üretmez.
//
// Görevleri:
//
// - Loruv API cevabını kontrol etmek
// - Ev sensörünü device_id ile bulmak
// - Çatı sensörünü device_id ile bulmak
// - Her sensörü ayrı ayrı doğrulamak
// - Sıcaklık / nem / pil / RSSI verilerini çıkarmak
// - Cihazın son saat kaydını çıkarmak
// - Veri yaşını kontrol etmek
// - Çiğ noktası hesaplamak
// - Yoğuşma risk göstergesi oluşturmak
// - Sensör sinyal sağlığını sınıflandırmak
//
// ÖNEMLİ:
// Bir sensör bozukken diğer sensörün verisini çöpe atmıyoruz.
// Örneğin Çatı okunamazsa Ev yine izlenmeye devam edebilir.
