// ============================================================
// 1. MERKEZİ AYARLARI AL
// ============================================================

const controlPlan =
    $("Merkezi Ayarlar + Kontrol Planı")
        .first()
        .json;


const CONFIG =
    controlPlan.config;


const zoneLimits =
    controlPlan.zoneLimits;


// HTTP Request node'undan gelen API cevabı.
const apiResponse =
    $json;



// ============================================================
// 2. YARDIMCI FONKSİYONLAR
// ============================================================


// ------------------------------------------------------------
// GEÇERLİ SAYI MI?
// ------------------------------------------------------------

function isFiniteNumber(value) {

    return (
        typeof value === "number" &&
        Number.isFinite(value)
    );

}


// ------------------------------------------------------------
// SAYIYA ÇEVİR
// ------------------------------------------------------------
//
// JSON içerisindeki sayı yanlışlıkla string gelirse de
// mümkün olduğunca güvenli biçimde kullanabilelim.
// ------------------------------------------------------------

function toFiniteNumber(value) {

    if (
        value === null ||
        value === undefined ||
        value === ""
    ) {

        return null;

    }


    const number =
        Number(value);


    return Number.isFinite(number)
        ? number
        : null;

}


// ------------------------------------------------------------
// VERİ YAŞI
// ------------------------------------------------------------

function calculateAgeMinutes(dateValue) {

    if (!dateValue) {

        return null;

    }


    const timestamp =
        new Date(dateValue)
            .getTime();


    if (
        !Number.isFinite(timestamp)
    ) {

        return null;

    }


    return (
        Date.now() -
        timestamp
    ) / 60000;

}


// ------------------------------------------------------------
// ÇİĞ NOKTASI
// ------------------------------------------------------------
//
// Magnus yaklaşımı.
//
// Ortam sıcaklığı ile bağıl nem kullanılarak
// yaklaşık dew point hesaplanır.
//
// Bu:
// "elektronik üzerinde kesin yoğuşma var"
// anlamına GELMEZ.
//
// Çünkü cihaz yüzey sıcaklığını bilmiyoruz.
//
// Ancak sıcaklık ile dew point arasındaki fark küçüldükçe
// yoğuşma ihtimali açısından daha dikkatli olmak gerekir.
// ------------------------------------------------------------

function calculateDewPoint(
    temperatureC,
    humidityPercent
) {

    if (
        !isFiniteNumber(temperatureC) ||
        !isFiniteNumber(humidityPercent)
    ) {

        return null;

    }


    if (
        humidityPercent <= 0 ||
        humidityPercent > 100
    ) {

        return null;

    }


    const a =
        17.62;


    const b =
        243.12;


    const gamma =
        Math.log(
            humidityPercent / 100
        ) +
        (
            a *
            temperatureC
        ) /
        (
            b +
            temperatureC
        );


    const dewPoint =
        (
            b *
            gamma
        ) /
        (
            a -
            gamma
        );


    return Number(
        dewPoint.toFixed(2)
    );

}


// ------------------------------------------------------------
// YOĞUŞMA RİSK GÖSTERGESİ
// ------------------------------------------------------------

function calculateCondensationRisk(
    temperatureC,
    dewPointC
) {

    if (
        !CONFIG.condensation.enabled ||
        !isFiniteNumber(temperatureC) ||
        !isFiniteNumber(dewPointC)
    ) {

        return {

            available: false,

            spreadC: null,

            level: "unknown",

        };

    }


    const spread =
        Number(
            (
                temperatureC -
                dewPointC
            ).toFixed(2)
        );


    let level =
        "normal";


    if (
        spread <=
        CONFIG.condensation
            .criticalSpreadC
    ) {

        level =
            "critical";

    }


    else if (
        spread <=
        CONFIG.condensation
            .warningSpreadC
    ) {

        level =
            "warning";

    }


    return {

        available: true,

        spreadC: spread,

        level,

    };

}


// ------------------------------------------------------------
// RSSI SAĞLIK DURUMU
// ------------------------------------------------------------

function calculateSignalHealth(
    rssi
) {

    if (!isFiniteNumber(rssi)) {

        return "unknown";

    }


    if (
        rssi <=
        CONFIG.sensorHealth
            .criticalSignalDbm
    ) {

        return "critical";

    }


    if (
        rssi <=
        CONFIG.sensorHealth
            .weakSignalDbm
    ) {

        return "warning";

    }


    return "normal";

}


// ------------------------------------------------------------
// PİL SAĞLIK DURUMU
// ------------------------------------------------------------
//
// Şimdilik voltaj eşikleri null olduğu için alarm üretmeyecek.
//
// Daha sonra gerçek LYWSD03MMC pil davranışını gördüğümüzde
// sadece CONFIG içinden eşik vermemiz yeterli olacak.
// ------------------------------------------------------------

function calculateBatteryHealth(
    voltage
) {

    if (!isFiniteNumber(voltage)) {

        return "unknown";

    }


    const criticalVoltage =
        CONFIG.sensorHealth
            .batteryCriticalVoltage;


    const warningVoltage =
        CONFIG.sensorHealth
            .batteryWarningVoltage;


    if (
        isFiniteNumber(criticalVoltage) &&
        voltage <= criticalVoltage
    ) {

        return "critical";

    }


    if (
        isFiniteNumber(warningVoltage) &&
        voltage <= warningVoltage
    ) {

        return "warning";

    }


    // Voltaj mevcut fakat eşikler tanımlı değil.
    return "monitoring";

}



// ============================================================
// 3. API GENEL DOĞRULAMA
// ============================================================

const globalErrors =
    [];


let devices =
    [];


// API cevabında devices array var mı?
if (
    Array.isArray(
        apiResponse?.devices
    )
) {

    devices =
        apiResponse.devices;

}

else {

    globalErrors.push(
        "API cevabında devices dizisi bulunamadı."
    );

}


// API success false ise bunu da kaydet.
if (
    apiResponse?.success === false
) {

    globalErrors.push(
        "Loruv Climate Bridge API success=false döndürdü."
    );

}



// ============================================================
// 4. TEK BİR BÖLGE / SENSÖRÜ HAZIRLAYAN FONKSİYON
// ============================================================

function prepareZone(
    zoneKey,
    sensorConfig
) {

    // --------------------------------------------------------
    // SENSÖRÜ DEVICE_ID İLE BUL
    // --------------------------------------------------------

    const device =
        devices.find(
            item =>
                item?.device_id ===
                sensorConfig.deviceId
        );


    const errors =
        [];


    // --------------------------------------------------------
    // SENSÖR BULUNAMADI
    // --------------------------------------------------------

    if (!device) {

        return {

            zoneKey,

            zoneName:
                sensorConfig.name,

            deviceId:
                sensorConfig.deviceId,

            found:
                false,

            valid:
                false,

            errors: [
                `${sensorConfig.name} sensörü API cevabında bulunamadı.`,
            ],

            limits:
                zoneLimits[zoneKey] ??
                null,

        };

    }


    // ========================================================
    // 5. ANA ÖLÇÜMLER
    // ========================================================

    const temperatureC =
        toFiniteNumber(
            device?.decoded
                ?.measurements
                ?.temperature_c
        );


    const humidityPercent =
        toFiniteNumber(
            device?.decoded
                ?.measurements
                ?.humidity_percent
        );


    const batteryVoltage =
        toFiniteNumber(
            device?.decoded
                ?.battery
                ?.voltage_v
        );


    const batteryReportedPercent =
        toFiniteNumber(
            device?.decoded
                ?.battery
                ?.reported_percent
        );


    const rssiDbm =
        toFiniteNumber(
            device?.advertisement
                ?.rssi_dbm
        );


    const readAt =
        device?.read_at ??
        null;


    const dataAgeMinutes =
        calculateAgeMinutes(
            readAt
        );



    // ========================================================
    // 6. CİHAZIN SON SAAT KAYDI
    // ========================================================

    const lastHourRecord =
        device?.decoded
            ?.history
            ?.last_hour_record ??
        null;


    const lastHour = {

        available:
            Boolean(lastHourRecord),


        recordIndex:
            lastHourRecord
                ?.record_index ??
            null,


        temperatureMaxC:
            toFiniteNumber(
                lastHourRecord
                    ?.temperature_max_c
            ),


        temperatureMinC:
            toFiniteNumber(
                lastHourRecord
                    ?.temperature_min_c
            ),


        humidityMaxPercent:
            toFiniteNumber(
                lastHourRecord
                    ?.humidity_max_percent
            ),


        humidityMinPercent:
            toFiniteNumber(
                lastHourRecord
                    ?.humidity_min_percent
            ),


        timestampRaw:
            lastHourRecord
                ?.timestamp_raw ??
            null,


        timestampIsoUtc:
            lastHourRecord
                ?.timestamp_iso_utc_if_plausible ??
            null,

    };



    // ========================================================
    // 7. VERİ DOĞRULAMA
    // ========================================================


    // Cihaz online mı?
    if (
        device?.status !==
        "online"
    ) {

        errors.push(
            `${sensorConfig.name} sensörü online değil. Durum: ${device?.status ?? "bilinmiyor"}`
        );

    }


    // Sıcaklık var mı?
    if (
        !isFiniteNumber(
            temperatureC
        )
    ) {

        errors.push(
            `${sensorConfig.name} sensöründen geçerli sıcaklık alınamadı.`
        );

    }


    // Nem var mı?
    if (
        !isFiniteNumber(
            humidityPercent
        )
    ) {

        errors.push(
            `${sensorConfig.name} sensöründen geçerli nem alınamadı.`
        );

    }


    // Nem fiziksel olarak makul aralıkta mı?
    if (
        isFiniteNumber(
            humidityPercent
        ) &&
        (
            humidityPercent < 0 ||
            humidityPercent > 100
        )
    ) {

        errors.push(
            `${sensorConfig.name} sensörü geçersiz nem değeri döndürdü: %${humidityPercent}`
        );

    }


    // read_at var mı?
    if (
        dataAgeMinutes === null
    ) {

        errors.push(
            `${sensorConfig.name} sensörünün read_at zamanı doğrulanamadı.`
        );

    }


    // Veri çok eski mi?
    else if (
        dataAgeMinutes >
        CONFIG.api
            .maxDataAgeMinutes
    ) {

        errors.push(
            `${sensorConfig.name} sensör verisi eski: ${Math.round(dataAgeMinutes)} dakika.`
        );

    }



    // ========================================================
    // 8. DEW POINT
    // ========================================================

    const dewPointC =
        calculateDewPoint(
            temperatureC,
            humidityPercent
        );


    const condensation =
        calculateCondensationRisk(
            temperatureC,
            dewPointC
        );



    // ========================================================
    // 9. SENSÖR SAĞLIĞI
    // ========================================================

    const signalHealth =
        calculateSignalHealth(
            rssiDbm
        );


    const batteryHealth =
        calculateBatteryHealth(
            batteryVoltage
        );



    // ========================================================
    // 10. SON 1 SAAT + ŞİMDİKİ DEĞERLERİN BİRLEŞTİRİLMESİ
    // ========================================================
    //
    // Alarm motoru daha sonra bunları kullanacak.
    //
    // Örneğin şu an 38 °C olsa bile cihazın son saat kaydında
    // 41 °C görülmüşse bunu kaçırmayacağız.
    // ========================================================

    const temperatureMaxCandidates =
        [
            temperatureC,
            lastHour.temperatureMaxC,
        ]
        .filter(
            isFiniteNumber
        );


    const temperatureMinCandidates =
        [
            temperatureC,
            lastHour.temperatureMinC,
        ]
        .filter(
            isFiniteNumber
        );


    const humidityMaxCandidates =
        [
            humidityPercent,
            lastHour.humidityMaxPercent,
        ]
        .filter(
            isFiniteNumber
        );


    const humidityMinCandidates =
        [
            humidityPercent,
            lastHour.humidityMinPercent,
        ]
        .filter(
            isFiniteNumber
        );


    const observed = {

        temperatureMaxC:
            temperatureMaxCandidates.length
                ? Math.max(
                    ...temperatureMaxCandidates
                )
                : null,


        temperatureMinC:
            temperatureMinCandidates.length
                ? Math.min(
                    ...temperatureMinCandidates
                )
                : null,


        humidityMaxPercent:
            humidityMaxCandidates.length
                ? Math.max(
                    ...humidityMaxCandidates
                )
                : null,


        humidityMinPercent:
            humidityMinCandidates.length
                ? Math.min(
                    ...humidityMinCandidates
                )
                : null,

    };



    // ========================================================
    // 11. BÖLGE OUTPUT
    // ========================================================

    return {

        zoneKey,

        zoneName:
            sensorConfig.name,


        deviceId:
            sensorConfig.deviceId,


        deviceName:
            device?.name ??
            sensorConfig.name,


        macAddress:
            device?.mac_address ??
            null,


        found:
            true,


        valid:
            errors.length === 0,


        errors,


        status:
            device?.status ??
            "unknown",


        readAt,


        dataAgeMinutes:
            dataAgeMinutes !== null
                ? Number(
                    dataAgeMinutes.toFixed(2)
                )
                : null,


        // ----------------------------------------------------
        // ŞU AN
        // ----------------------------------------------------

        current: {

            temperatureC,

            humidityPercent,

        },


        // ----------------------------------------------------
        // SON SAAT
        // ----------------------------------------------------

        lastHour,


        // ----------------------------------------------------
        // ŞU AN + SON SAAT EN KÖTÜ DEĞERLER
        // ----------------------------------------------------

        observed,


        // ----------------------------------------------------
        // ÇİĞ NOKTASI
        // ----------------------------------------------------

        dewPoint: {

            temperatureC:
                dewPointC,

            spreadC:
                condensation.spreadC,

            risk:
                condensation.level,

            available:
                condensation.available,

        },


        // ----------------------------------------------------
        // SENSÖR SAĞLIĞI
        // ----------------------------------------------------

        sensorHealth: {

            rssiDbm,

            signal:
                signalHealth,


            batteryVoltage,

            batteryReportedPercent,

            battery:
                batteryHealth,

        },


        // ----------------------------------------------------
        // BU BÖLGENİN EKİPMAN LİMİTLERİ
        // ----------------------------------------------------

        limits:
            zoneLimits[zoneKey] ??
            null,

    };

}



// ============================================================
// 12. EV + ÇATIYI HAZIRLA
// ============================================================

const home =
    prepareZone(
        "home",
        CONFIG.sensors.home
    );


const attic =
    prepareZone(
        "attic",
        CONFIG.sensors.attic
    );



const zones = {

    home,

    attic,

};



// ============================================================
// 13. GENEL DURUM
// ============================================================

const validZoneCount =
    Object
        .values(zones)
        .filter(
            zone =>
                zone.valid
        )
        .length;


const invalidZoneCount =
    Object
        .values(zones)
        .filter(
            zone =>
                !zone.valid
        )
        .length;


const allZonesValid =
    invalidZoneCount === 0;


const atLeastOneZoneValid =
    validZoneCount > 0;



// ============================================================
// 14. OUTPUT
// ============================================================

return [
    {
        json: {

            // HTTP isteği başarılı output'tan geldi.
            transportOk:
                true,


            // API'nin genel durumu.
            api: {

                service:
                    apiResponse?.service ??
                    null,

                apiVersion:
                    apiResponse?.api_version ??
                    null,

                success:
                    apiResponse?.success ??
                    null,

                cached:
                    apiResponse?.cached ??
                    null,

                cacheAgeSeconds:
                    apiResponse?.cache_age_seconds ??
                    null,

                capturedAt:
                    apiResponse?.captured_at ??
                    null,

                deviceCount:
                    apiResponse?.device_count ??
                    devices.length,

                globalErrors,

            },


            // Zamanlama bilgisini kaybetmiyoruz.
            schedule: {

                season:
                    controlPlan.season,

                priorityWindow:
                    controlPlan.priorityWindow,

                reason:
                    controlPlan.scheduleReason,

                description:
                    controlPlan.scheduleDescription,

                isDailyReportTime:
                    controlPlan.isDailyReportTime,

                localTime:
                    controlPlan.localTime,

            },


            // Ev + Çatı.
            zones,


            // Genel doğrulama.
            validation: {

                allZonesValid,

                atLeastOneZoneValid,

                validZoneCount,

                invalidZoneCount,

            },

        },
    },
];

