    );

}



// ============================================================
// 4. TEK BİR BÖLGE / SENSÖRÜ HAZIRLAYAN FONKSİYON
// ============================================================

function prepareZone(
    zoneKey,
    sensorConfig
) {

    // --------------------------------------------------------
    // SENSÖRÜ DEVICE_ID İLE BUL
    // --------------------------------------------------------

    const device =
        devices.find(
            item =>
                item?.device_id ===
                sensorConfig.deviceId
        );


    const errors =
        [];


    // --------------------------------------------------------
    // SENSÖR BULUNAMADI
    // --------------------------------------------------------

    if (!device) {

        return {

            zoneKey,

            zoneName:
                sensorConfig.name,

            deviceId:
                sensorConfig.deviceId,

            found:
                false,

            valid:
                false,

            errors: [
                `${sensorConfig.name} sensörü API cevabında bulunamadı.`,
            ],

            limits:
                zoneLimits[zoneKey] ??
                null,

        };

    }


    // ========================================================
    // 5. ANA ÖLÇÜMLER
    // ========================================================

    const temperatureC =
        toFiniteNumber(
            device?.decoded
                ?.measurements
                ?.temperature_c
        );


    const humidityPercent =
        toFiniteNumber(
            device?.decoded
                ?.measurements
                ?.humidity_percent
        );


    const batteryVoltage =
        toFiniteNumber(
            device?.decoded
                ?.battery
                ?.voltage_v
        );


    const batteryReportedPercent =
        toFiniteNumber(
            device?.decoded
                ?.battery
                ?.reported_percent
        );


    const rssiDbm =
        toFiniteNumber(
            device?.advertisement
                ?.rssi_dbm
        );


    const readAt =
        device?.read_at ??
        null;


    const dataAgeMinutes =
        calculateAgeMinutes(
            readAt
        );



    // ========================================================
    // 6. CİHAZIN SON SAAT KAYDI
    // ========================================================

    const lastHourRecord =
        device?.decoded
            ?.history
            ?.last_hour_record ??
        null;


    const lastHour = {

        available:
            Boolean(lastHourRecord),


        recordIndex:
            lastHourRecord
                ?.record_index ??
            null,


        temperatureMaxC:
            toFiniteNumber(
                lastHourRecord
                    ?.temperature_max_c
            ),


        temperatureMinC:
            toFiniteNumber(
                lastHourRecord
                    ?.temperature_min_c
            ),


        humidityMaxPercent:
            toFiniteNumber(
                lastHourRecord
                    ?.humidity_max_percent
            ),


        humidityMinPercent:
            toFiniteNumber(
                lastHourRecord
                    ?.humidity_min_percent
            ),


        timestampRaw:
            lastHourRecord
                ?.timestamp_raw ??
            null,


        timestampIsoUtc:
            lastHourRecord
                ?.timestamp_iso_utc_if_plausible ??
            null,

    };



    // ========================================================
    // 7. VERİ DOĞRULAMA
    // ========================================================


    // Cihaz online mı?
    if (
        device?.status !==
        "online"
    ) {

        errors.push(
            `${sensorConfig.name} sensörü online değil. Durum: ${device?.status ?? "bilinmiyor"}`
        );

    }


    // Sıcaklık var mı?
    if (
        !isFiniteNumber(
            temperatureC
        )
    ) {

        errors.push(
            `${sensorConfig.name} sensöründen geçerli sıcaklık alınamadı.`
        );

    }


    // Nem var mı?
    if (
        !isFiniteNumber(
            humidityPercent
        )
    ) {

        errors.push(
            `${sensorConfig.name} sensöründen geçerli nem alınamadı.`
        );

    }


    // Nem fiziksel olarak makul aralıkta mı?
    if (
        isFiniteNumber(
            humidityPercent
        ) &&
        (
            humidityPercent < 0 ||
            humidityPercent > 100
        )
    ) {

        errors.push(
            `${sensorConfig.name} sensörü geçersiz nem değeri döndürdü: %${humidityPercent}`
        );

    }


    // read_at var mı?
    if (
        dataAgeMinutes === null
    ) {

        errors.push(
            `${sensorConfig.name} sensörünün read_at zamanı doğrulanamadı.`
        );

    }


    // Veri çok eski mi?
    else if (
        dataAgeMinutes >
        CONFIG.api
            .maxDataAgeMinutes
    ) {

        errors.push(
            `${sensorConfig.name} sensör verisi eski: ${Math.round(dataAgeMinutes)} dakika.`
        );

    }



    // ========================================================
    // 8. DEW POINT
    // ========================================================

    const dewPointC =
        calculateDewPoint(
            temperatureC,
            humidityPercent
        );


    const condensation =
        calculateCondensationRisk(
            temperatureC,
            dewPointC
        );



    // ========================================================
    // 9. SENSÖR SAĞLIĞI
    // ========================================================

    const signalHealth =
        calculateSignalHealth(
            rssiDbm
        );


    const batteryHealth =
        calculateBatteryHealth(
            batteryVoltage
        );



    // ========================================================
    // 10. SON 1 SAAT + ŞİMDİKİ DEĞERLERİN BİRLEŞTİRİLMESİ
    // ========================================================
    //
    // Alarm motoru daha sonra bunları kullanacak.
    //
    // Örneğin şu an 38 °C olsa bile cihazın son saat kaydında
    // 41 °C görülmüşse bunu kaçırmayacağız.
    // ========================================================

    const temperatureMaxCandidates =
        [
            temperatureC,
            lastHour.temperatureMaxC,
        ]
        .filter(
            isFiniteNumber
        );


    const temperatureMinCandidates =
        [
            temperatureC,
            lastHour.temperatureMinC,
        ]
        .filter(
            isFiniteNumber
        );


    const humidityMaxCandidates =
        [
            humidityPercent,
            lastHour.humidityMaxPercent,
        ]
        .filter(
            isFiniteNumber
        );


    const humidityMinCandidates =
        [
            humidityPercent,
            lastHour.humidityMinPercent,
        ]
        .filter(
            isFiniteNumber
        );


    const observed = {

        temperatureMaxC:
            temperatureMaxCandidates.length
                ? Math.max(
                    ...temperatureMaxCandidates
                )
                : null,


        temperatureMinC:
            temperatureMinCandidates.length
                ? Math.min(
                    ...temperatureMinCandidates
                )
                : null,


        humidityMaxPercent:
            humidityMaxCandidates.length
                ? Math.max(
                    ...humidityMaxCandidates
                )
                : null,


        humidityMinPercent:
            humidityMinCandidates.length
                ? Math.min(
                    ...humidityMinCandidates
                )
                : null,

    };



    // ========================================================
    // 11. BÖLGE OUTPUT
    // ========================================================

    return {

        zoneKey,

        zoneName:
            sensorConfig.name,


        deviceId:
            sensorConfig.deviceId,


        deviceName:
            device?.name ??
            sensorConfig.name,


        macAddress:
            device?.mac_address ??
            null,


        found:
            true,


        valid:
            errors.length === 0,


        errors,


        status:
            device?.status ??
            "unknown",


        readAt,


        dataAgeMinutes:
            dataAgeMinutes !== null
                ? Number(
                    dataAgeMinutes.toFixed(2)
                )
                : null,


        // ----------------------------------------------------
        // ŞU AN
        // ----------------------------------------------------

        current: {

            temperatureC,

            humidityPercent,

        },


        // ----------------------------------------------------
        // SON SAAT
        // ----------------------------------------------------

        lastHour,


        // ----------------------------------------------------
        // ŞU AN + SON SAAT EN KÖTÜ DEĞERLER
        // ----------------------------------------------------

        observed,


        // ----------------------------------------------------
        // ÇİĞ NOKTASI
        // ----------------------------------------------------

        dewPoint: {

            temperatureC:
                dewPointC,

            spreadC:
                condensation.spreadC,

            risk:
                condensation.level,

            available:
                condensation.available,

        },


        // ----------------------------------------------------
        // SENSÖR SAĞLIĞI
        // ----------------------------------------------------

        sensorHealth: {

            rssiDbm,

            signal:
                signalHealth,


            batteryVoltage,

            batteryReportedPercent,

            battery:
                batteryHealth,

        },


        // ----------------------------------------------------
        // BU BÖLGENİN EKİPMAN LİMİTLERİ
        // ----------------------------------------------------

        limits:
            zoneLimits[zoneKey] ??
            null,

    };

}



// ============================================================
// 12. EV + ÇATIYI HAZIRLA
// ============================================================

const home =
    prepareZone(
        "home",
        CONFIG.sensors.home
    );


const attic =
    prepareZone(
        "attic",
        CONFIG.sensors.attic
    );



const zones = {

    home,

    attic,

};



// ============================================================
// 13. GENEL DURUM
// ============================================================

const validZoneCount =
    Object
        .values(zones)
        .filter(
            zone =>
                zone.valid
        )
        .length;


const invalidZoneCount =
    Object
        .values(zones)
        .filter(
            zone =>
                !zone.valid
        )
        .length;


const allZonesValid =
    invalidZoneCount === 0;


const atLeastOneZoneValid =
    validZoneCount > 0;



// ============================================================
// 14. OUTPUT
// ============================================================

return [
    {
        json: {

            // HTTP isteği başarılı output'tan geldi.
            transportOk:
                true,


            // API'nin genel durumu.
            api: {

                service:
                    apiResponse?.service ??
                    null,

                apiVersion:
                    apiResponse?.api_version ??
                    null,

                success:
                    apiResponse?.success ??
                    null,

                cached:
                    apiResponse?.cached ??
                    null,

                cacheAgeSeconds:
                    apiResponse?.cache_age_seconds ??
                    null,

                capturedAt:
                    apiResponse?.captured_at ??
                    null,

                deviceCount:
                    apiResponse?.device_count ??
                    devices.length,

                globalErrors,

            },


            // Zamanlama bilgisini kaybetmiyoruz.
            schedule: {

                season:
                    controlPlan.season,

                priorityWindow:
                    controlPlan.priorityWindow,

                reason:
                    controlPlan.scheduleReason,

                description:
                    controlPlan.scheduleDescription,

                isDailyReportTime:
                    controlPlan.isDailyReportTime,

                localTime:
                    controlPlan.localTime,

            },


            // Ev + Çatı.
            zones,


            // Genel doğrulama.
            validation: {

                allZonesValid,

                atLeastOneZoneValid,

                validZoneCount,

                invalidZoneCount,

            },

        },
    },
];

// ============================================================
// LORUV ORTAM İZLEME SİSTEMİ
// NİHAİ SENSÖR DURUMU + VERİ ALARMI
// ============================================================
//
// Bu node maksimum sensör retry süreci tamamlandıktan sonra
// çalışır.
//
// Görevleri:
//
// - Ev ve Çatı sensörlerinin nihai veri durumunu kontrol etmek
// - Veri alınamayan sensörü ayrı takip etmek
// - İlk veri hatasında Telegram bildirimi hazırlamak
// - Aynı hatayı sürekli mesaj olarak göndermemek
// - Hata devam ederse belirli aralıklarla hatırlatmak
// - Sensör tekrar çalışırsa recovery mesajı hazırlamak
// - Bir sensör bozuk olsa bile diğer sensör verilerini korumak
//
// Bu node ortam sıcaklık/nem alarmını henüz üretmez.
// Bir sonraki alarm motoruna veriyi hazır halde aktarır.
// ============================================================



// ============================================================
// 1. MERKEZİ AYARLAR
// ============================================================

const controlPlan =
    $("Merkezi Ayarlar + Kontrol Planı")
        .first()
        .json;


const CONFIG =
    controlPlan.config;


// Bu node'a gelen nihai hazırlanmış sensör snapshot'ı.
const snapshot =
    $json;



// ============================================================
// 2. WORKFLOW KALICI DURUM HAFIZASI
// ============================================================
//
// Her sensörün daha önce hatalı olup olmadığını hatırlıyoruz.
//
// Böylece:
//
// 21:00 Ev hata
// → Telegram
//
// 00:00 Ev hâlâ hata
// → tekrar süresi dolmuşsa Telegram
//
// Ev düzelirse
// → recovery Telegram
//
// yapılabilir.
// ============================================================

const storage =
    $getWorkflowStaticData("global");


if (!storage.loruvSensorDataState) {

    storage.loruvSensorDataState = {

        zones: {},

    };

}


const persistent =
    storage.loruvSensorDataState;



// ============================================================
// 3. YARDIMCI FONKSİYONLAR
// ============================================================

function initializeZoneState(zoneKey) {

    if (!persistent.zones[zoneKey]) {

        persistent.zones[zoneKey] = {

            failureActive: false,

            consecutiveFailures: 0,

            lastFailureAlertAt: 0,

            lastSuccessfulReadAt: null,

            lastRecoveryAt: null,

        };

    }


    return persistent.zones[zoneKey];

}


function formatLocalTimestamp() {

    return new Intl.DateTimeFormat(
        "tr-TR",
        {
            timeZone:
                CONFIG.system.timezone,

            year:
                "numeric",

            month:
                "2-digit",

            day:
                "2-digit",

            hour:
                "2-digit",

            minute:
                "2-digit",

            second:
                "2-digit",

        }
    ).format(
        new Date()
    );

}


function formatLastSuccess(value) {

    if (!value) {

        return "Başarılı okuma kaydı bulunmuyor";

    }


    const date =
        new Date(value);


    if (
        Number.isNaN(
            date.getTime()
        )
    ) {

        return value;

    }


    return new Intl.DateTimeFormat(
        "tr-TR",
        {
            timeZone:
                CONFIG.system.timezone,

            year:
                "numeric",

            month:
                "2-digit",

            day:
                "2-digit",

            hour:
                "2-digit",

            minute:
                "2-digit",

        }
    ).format(date);

}



// ============================================================
// 4. BİLDİRİMLER
// ============================================================

const notifications =
    [];


const nowMs =
    Date.now();


const failureRepeatMs =
    CONFIG.alerts
        .dataFailureRepeatMinutes *
    60 *
    1000;



// ============================================================
// 5. TÜM BÖLGELERİ TEK TEK DEĞERLENDİR
// ============================================================

for (
    const [
        zoneKey,
        zone
    ]
    of Object.entries(
        snapshot.zones ?? {}
    )
) {

    const zoneState =
        initializeZoneState(
            zoneKey
        );


    // ========================================================
    // SENSÖR GEÇERLİ
    // ========================================================

    if (zone.valid === true) {

        // Daha önce sensör hatalı mıydı?
        const recovered =
            zoneState.failureActive;


        // Son başarılı okuma zamanını güncelle.
        zoneState.lastSuccessfulReadAt =
            zone.readAt ??
            new Date().toISOString();


        // Hata sayacını sıfırla.
        zoneState.consecutiveFailures =
            0;


        // Failure durumunu kapat.
        zoneState.failureActive =
            false;


        // ----------------------------------------------------
        // RECOVERY MESAJI
        // ----------------------------------------------------

        if (
            recovered &&
            CONFIG.alerts
                .sendDataRecovery
        ) {

            zoneState.lastRecoveryAt =
                nowMs;


            notifications.push({

                type:
                    "data_recovery",

                severity:
                    "info",

                zoneKey,

                zoneName:
                    zone.zoneName,

                message:
`🟢 <b>${zone.zoneName.toUpperCase()} SENSÖRÜ TEKRAR ÇALIŞIYOR</b>

Sensörden yeniden geçerli sıcaklık ve nem verisi alınmaya başlandı.

🌡 <b>Sıcaklık:</b> ${zone.current?.temperatureC ?? "?"} °C
💧 <b>Nem:</b> %${zone.current?.humidityPercent ?? "?"}

📶 <b>BLE RSSI:</b> ${zone.sensorHealth?.rssiDbm ?? "?"} dBm
🔋 <b>Pil:</b> ${zone.sensorHealth?.batteryVoltage ?? "?"} V

🕒 <b>Kontrol zamanı:</b> ${formatLocalTimestamp()}

✅ Loruv ortam izleme sistemi ${zone.zoneName} sensörünü yeniden sağlıklı şekilde okuyabiliyor.`,

            });

        }


        continue;

    }



    // ========================================================
    // SENSÖR GEÇERSİZ / VERİ ALINAMADI
    // ========================================================

    zoneState.consecutiveFailures +=
        1;


    const firstFailure =
        !zoneState.failureActive;


    const repeatDue =
        (
            nowMs -
            zoneState.lastFailureAlertAt
        ) >=
        failureRepeatMs;


    zoneState.failureActive =
        true;


    // İlk hata veya tekrar süresi dolduysa mesaj üret.
    const shouldNotify =
        firstFailure ||
        repeatDue;


    if (!shouldNotify) {

        continue;

    }


    zoneState.lastFailureAlertAt =
        nowMs;



    // --------------------------------------------------------
    // HATA SEBEPLERİ
    // --------------------------------------------------------

    const errorLines =
        Array.isArray(
            zone.errors
        ) &&
        zone.errors.length > 0

            ? zone.errors
                .map(
                    error =>
                        `• ${error}`
                )
                .join("\
")

            : "• Sensörden geçerli veri alınamadı.";



    // --------------------------------------------------------
    // İLK HATA / TEKRAR HATIRLATMA
    // --------------------------------------------------------

    const title =
        firstFailure
            ? `🔴 <b>${zone.zoneName.toUpperCase()} SENSÖR VERİ HATASI</b>`
            : `🔴 <b>${zone.zoneName.toUpperCase()} SENSÖR HATASI DEVAM EDİYOR</b>`;



    notifications.push({

        type:
            firstFailure
                ? "data_failure"
                : "data_failure_repeat",

        severity:
            "critical",

        zoneKey,

        zoneName:
            zone.zoneName,

        message:
`${title}

Loruv Ortam İzleme Sistemi ${zone.zoneName} sensöründen geçerli veri alamadı.

<b>Tespit edilen sorunlar:</b>
${errorLines}

🔁 <b>Ardışık başarısız kontrol:</b> ${zoneState.consecutiveFailures}

📡 <b>Sensör bulundu:</b> ${zone.found ? "Evet" : "Hayır"}
📊 <b>Sensör durumu:</b> ${zone.status ?? "Bilinmiyor"}

📶 <b>Son görülen RSSI:</b> ${zone.sensorHealth?.rssiDbm ?? "Bilinmiyor"} dBm

✅ <b>Son başarılı okuma:</b>
${formatLastSuccess(zoneState.lastSuccessfulReadAt)}

🕒 <b>Kontrol zamanı:</b>
${formatLocalTimestamp()}

Kontrol edilmesi önerilenler:
• LYWSD03MMC sensörünün açık ve erişilebilir olması
• Raspberry Pi Bluetooth bağlantısı
• Sensör ile Raspberry Pi arasındaki mesafe
• Loruv Climate Bridge container logları

⚠️ Diğer çalışan sensörler izlenmeye devam edecektir.`,

    });

}



// ============================================================
// 6. GEÇERLİ VE GEÇERSİZ BÖLGELERİ ÇIKAR
// ============================================================

const validZones =
    Object.values(
        snapshot.zones ?? {}
    )
    .filter(
        zone =>
            zone.valid === true
    )
    .map(
        zone =>
            zone.zoneKey
    );


const invalidZones =
    Object.values(
        snapshot.zones ?? {}
    )
    .filter(
        zone =>
            zone.valid !== true
    )
    .map(
        zone =>
            zone.zoneKey
    );



// ============================================================
// 7. OUTPUT
// ============================================================
//
// snapshot'ın tamamını koruyoruz.
//
// Böylece bir sonraki ortam alarm motoru:
// - Ev geçerliyse Ev'i,
// - Çatı geçerliyse Çatı'yı
// analiz etmeye devam edebilir.
// ============================================================

return [
    {
        json: {

            ...snapshot,


            dataMonitoring: {

                shouldNotify:
                    notifications.length > 0,

                notificationCount:
                    notifications.length,

                notifications,

                validZones,

                invalidZones,

                allZonesValid:
                    invalidZones.length === 0,

                atLeastOneZoneValid:
                    validZones.length > 0,

            },

        },
    },
];

// ============================================================
// LORUV ORTAM İZLEME SİSTEMİ
// VERİ BİLDİRİMLERİNİ AYIR
// ============================================================
//
// Nihai Sensör Durumu + Veri Alarmı node'u aynı anda
// birden fazla bildirim oluşturabilir.
//
// Örneğin:
//
// Ev   → veri alınamıyor
// Çatı → veri alınamıyor
//
// notifications dizisi:
//
// [
//   { Ev mesajı },
//   { Çatı mesajı }
// ]
//
// şeklinde gelir.
//
// Telegram node'u her n8n item'ı için ayrı çalıştığı için
// buradaki her bildirimi bağımsız item'a dönüştürüyoruz.
// ============================================================


// ============================================================
// 1. GELEN ITEM'LARI AL
// ============================================================

const inputItems =
    $input.all();


// ============================================================
// 2. TELEGRAM'A GÖNDERİLECEK ITEM'LAR
// ============================================================

const outputItems =
    [];


// ============================================================
// 3. TÜM INPUT'LARI İŞLE
// ============================================================

for (const inputItem of inputItems) {

    const notifications =
        inputItem.json
            ?.dataMonitoring
            ?.notifications;


    // Bildirim dizisi yoksa veya boşsa hiçbir şey üretme.
    if (
        !Array.isArray(notifications) ||
        notifications.length === 0
    ) {

        continue;

    }


    // ========================================================
    // 4. HER BİLDİRİMİ AYRI N8N ITEM'INA DÖNÜŞTÜR
    // ========================================================

    for (const notification of notifications) {

        // Mesaj yoksa Telegram'a boş mesaj göndermeyelim.
        if (
            typeof notification?.message !== "string" ||
            notification.message.trim() === ""
        ) {

            continue;

        }


        outputItems.push({

            json: {

                // Telegram'a gönderilecek asıl mesaj.
                message:
                    notification.message,


                // Bildirim tipi.
                //
                // Örnek:
                // data_failure
                // data_failure_repeat
                // data_recovery
                type:
                    notification.type ?? "unknown",


                // Önem seviyesi.
                severity:
                    notification.severity ?? "unknown",


                // Bölge.
                zoneKey:
                    notification.zoneKey ?? null,

                zoneName:
                    notification.zoneName ?? null,


                // İleride Telegram mesajlarını,
                // logları veya farklı kanalları ayırmak için
                // yararlı metadata.
                source:
                    "sensor_data_monitoring",

            },

        });

    }

}


// ============================================================
// 5. OUTPUT
// ============================================================

return outputItems;

// ============================================================
// LORUV ORTAM İZLEME SİSTEMİ
// ORTAM GÜVENLİK ALARM MOTORU
// ============================================================
//
// Bu node:
//
// - Ev ve Çatı'yı bağımsız değerlendirir
// - Sadece geçerli sensörleri analiz eder
// - Anlık sıcaklık ve nemi kontrol eder
// - Son 1 saat min/max kayıtlarını inceler
// - Çiğ noktası / yoğuşma riskini değerlendirir
// - RSSI sağlığını ayrı değerlendirir
// - Hysteresis uygular
// - Warning / Critical / Recovery üretir
// - Alarm spam'ini engeller
// - Günlük sağlık raporu hazırlar
//
// Bir sensör çalışmıyorsa diğer bölgenin ortam takibi
// çalışmaya devam eder.
// ============================================================



// ============================================================
// 1. MERKEZİ AYARLAR
// ============================================================

const controlPlan =
    $("Merkezi Ayarlar + Kontrol Planı")
        .first()
        .json;


const CONFIG =
    controlPlan.config;


// Nihai sensör snapshot'ı.
const snapshot =
    $json;



// ============================================================
// 2. KALICI WORKFLOW STATE
// ============================================================

const storage =
    $getWorkflowStaticData("global");


if (!storage.loruvEnvironmentMonitor) {

    storage.loruvEnvironmentMonitor = {

        zones: {},

        lastDailyReportDate: null,

    };

}


const persistent =
    storage.loruvEnvironmentMonitor;



// ============================================================
// 3. YARDIMCI FONKSİYONLAR
// ============================================================

function isNumber(value) {

    return (
        typeof value === "number" &&
        Number.isFinite(value)
    );

}


function formatNumber(
    value,
    digits = 1,
    fallback = "Bilinmiyor"
) {

    if (!isNumber(value)) {

        return fallback;

    }


    return value.toFixed(digits);

}


function formatLocalDateTime() {

    return new Intl.DateTimeFormat(
        "tr-TR",
        {
            timeZone:
                CONFIG.system.timezone,

            year:
                "numeric",

            month:
                "2-digit",

            day:
                "2-digit",

            hour:
                "2-digit",

            minute:
                "2-digit",

        }
    ).format(
        new Date()
    );

}


function getTodayKey() {

    const local =
        controlPlan.localTime;


    return [
        local.year,
        String(local.month).padStart(2, "0"),
        String(local.day).padStart(2, "0"),
    ].join("-");

}



// ============================================================
// 4. BÖLGE STATE BAŞLAT
// ============================================================

function getZoneState(zoneKey) {

    if (!persistent.zones[zoneKey]) {

        persistent.zones[zoneKey] = {

            environmentState:
                "normal",

            lastEnvironmentAlertAt:
                0,

            lastCriticalAt:
                null,

            lastWarningAt:
                null,

            lastRecoveryAt:
                null,

            signalState:
                "normal",

            lastSignalAlertAt:
                0,

            lastHistoryAlertRecord:
                null,

        };

    }


    return persistent.zones[zoneKey];

}



// ============================================================
// 5. LIMIT BELİRLEYEN EKİPMANLARI YAZDIR
// ============================================================

function joinEquipment(list) {

    if (
        !Array.isArray(list) ||
        list.length === 0
    ) {

        return "Bilinmiyor";

    }


    return list.join(", ");

}



// ============================================================
// 6. SON 1 SAAT METNİ
// ============================================================

function createLastHourText(zone) {

    const history =
        zone.lastHour;


    if (!history?.available) {

        return `📊 <b>Son 1 Saat</b>
Kayıt bulunamadı.`;

    }


    return `📊 <b>Son 1 Saat</b>
🔥 Max sıcaklık: ${formatNumber(history.temperatureMaxC)} °C
❄️ Min sıcaklık: ${formatNumber(history.temperatureMinC)} °C
💧 Max nem: %${formatNumber(history.humidityMaxPercent, 0)}
💧 Min nem: %${formatNumber(history.humidityMinPercent, 0)}`;

}



// ============================================================
// 7. ANLIK ORTAM DURUMUNU HESAPLA
// ============================================================

function calculateCurrentState(zone) {

    const temperature =
        zone.current?.temperatureC;


    const humidity =
        zone.current?.humidityPercent;


    const limits =
        zone.limits;


    const criticalReasons =
        [];


    const warningReasons =
        [];


    if (
        !limits ||
        !isNumber(temperature) ||
        !isNumber(humidity)
    ) {

        return {

            state:
                "unknown",

            criticalReasons,

            warningReasons,

        };

    }


    // ========================================================
    // KRİTİK SICAKLIK
    // ========================================================

    if (
        temperature >=
        limits.critical.temperature.max
    ) {

        criticalReasons.push(
            `Sıcaklık üst kritik sınırı aştı: ${temperature.toFixed(1)} °C ≥ ${limits.critical.temperature.max} °C`
        );

    }


    if (
        temperature <=
        limits.critical.temperature.min
    ) {

        criticalReasons.push(
            `Sıcaklık alt kritik sınırı aştı: ${temperature.toFixed(1)} °C ≤ ${limits.critical.temperature.min} °C`
        );

    }


    // ========================================================
    // KRİTİK NEM
    // ========================================================

    if (
        humidity >=
        limits.critical.humidity.max
    ) {

        criticalReasons.push(
            `Nem üst kritik sınırı aştı: %${humidity} ≥ %${limits.critical.humidity.max}`
        );

    }


    if (
        humidity <=
        limits.critical.humidity.min
    ) {

        criticalReasons.push(
            `Nem alt kritik sınırı aştı: %${humidity} ≤ %${limits.critical.humidity.min}`
        );

    }


    // ========================================================
    // YOĞUŞMA RİSKİ
    // ========================================================

    if (
        zone.dewPoint?.risk ===
        "critical"
    ) {

        criticalReasons.push(
            `Çiğ noktası farkı ${formatNumber(zone.dewPoint.spreadC, 2)} °C — yüksek yoğuşma riski`
        );

    }


    // Kritik varsa warning'e bakmaya gerek yok.
    if (
        criticalReasons.length > 0
    ) {

        return {

            state:
                "critical",

            criticalReasons,

            warningReasons,

        };

    }


    // ========================================================
    // WARNING SICAKLIK
    // ========================================================

    if (
        temperature >=
        limits.warning.temperature.max
    ) {

        warningReasons.push(
            `Sıcaklık üst sınıra yaklaşıyor: ${temperature.toFixed(1)} °C`
        );

    }


    if (
        temperature <=
        limits.warning.temperature.min
    ) {

        warningReasons.push(
            `Sıcaklık alt sınıra yaklaşıyor: ${temperature.toFixed(1)} °C`
        );

    }


    // ========================================================
    // WARNING NEM
    // ========================================================

    if (
        humidity >=
        limits.warning.humidity.max
    ) {

        warningReasons.push(
            `Nem üst sınıra yaklaşıyor: %${humidity}`
        );

    }


    if (
        humidity <=
        limits.warning.humidity.min
    ) {

        warningReasons.push(
            `Nem alt sınıra yaklaşıyor: %${humidity}`
        );

    }


    if (
        zone.dewPoint?.risk ===
        "warning"
    ) {

        warningReasons.push(
            `Çiğ noktası farkı ${formatNumber(zone.dewPoint.spreadC, 2)} °C — yoğuşma açısından dikkat`
        );

    }


    return {

        state:
            warningReasons.length > 0
                ? "warning"
                : "normal",

        criticalReasons,

        warningReasons,

    };

}



// ============================================================
// 8. CRITICAL RECOVERY HYSTERESIS
// ============================================================

function safeFromCritical(zone) {

    const t =
        zone.current.temperatureC;


    const h =
        zone.current.humidityPercent;


    const limits =
        zone.limits.critical;


    const tH =
        CONFIG.hysteresis
            .temperatureC;


    const hH =
        CONFIG.hysteresis
            .humidityPercent;


    return (

        t <
            limits.temperature.max -
            tH

        &&

        t >
            limits.temperature.min +
            tH

        &&

        h <
            limits.humidity.max -
            hH

        &&

        h >
            limits.humidity.min +
            hH

        &&

        zone.dewPoint?.risk !==
            "critical"

    );

}



// ============================================================
// 9. WARNING RECOVERY HYSTERESIS
// ============================================================

function safeFromWarning(zone) {

    const t =
        zone.current.temperatureC;


    const h =
        zone.current.humidityPercent;


    const limits =
        zone.limits.warning;


    const tH =
        CONFIG.hysteresis
            .temperatureC;


    const hH =
        CONFIG.hysteresis
            .humidityPercent;


    return (

        t <
            limits.temperature.max -
            tH

        &&

        t >
            limits.temperature.min +
            tH

        &&

        h <
            limits.humidity.max -
            hH

        &&

        h >
            limits.humidity.min +
            hH

        &&

        zone.dewPoint?.risk ===
            "normal"

    );

}



// ============================================================
// 10. SON 1 SAATTE KRİTİK SINIR AŞILDI MI?
// ============================================================
//
// Anlık değer normale dönmüş olsa bile son saat kaydında
// kritik sınır aşımı varsa bunu tamamen kaçırmayalım.
//
// Fakat aynı history record için yalnızca bir kez bildiririz.
// ============================================================

function getHistoricalCriticalReasons(zone) {

    const history =
        zone.lastHour;


    const limits =
        zone.limits?.critical;


    const reasons =
        [];


    if (
        !history?.available ||
        !limits
    ) {

        return reasons;

    }


    if (
        isNumber(history.temperatureMaxC) &&
        history.temperatureMaxC >=
            limits.temperature.max
    ) {

        reasons.push(
            `Son 1 saatte sıcaklık ${history.temperatureMaxC.toFixed(1)} °C'ye ulaştı`
        );

    }


    if (
        isNumber(history.temperatureMinC) &&
        history.temperatureMinC <=
            limits.temperature.min
    ) {

        reasons.push(
            `Son 1 saatte sıcaklık ${history.temperatureMinC.toFixed(1)} °C'ye düştü`
        );

    }


    if (
        isNumber(history.humidityMaxPercent) &&
        history.humidityMaxPercent >=
            limits.humidity.max
    ) {

        reasons.push(
            `Son 1 saatte nem %${history.humidityMaxPercent}'e ulaştı`
        );

    }


    if (
        isNumber(history.humidityMinPercent) &&
        history.humidityMinPercent <=
            limits.humidity.min
    ) {

        reasons.push(
            `Son 1 saatte nem %${history.humidityMinPercent}'e düştü`
        );

    }


    return reasons;

}



// ============================================================
// 11. NOTIFICATIONS
// ============================================================

const notifications =
    [];


const analyzedZones =
    {};


const nowMs =
    Date.now();



// ============================================================
// 12. EV + ÇATI ANALİZİ
// ============================================================

for (
    const [
        zoneKey,
        zone
    ]
    of Object.entries(
        snapshot.zones ?? {}
    )
) {

    // Geçersiz sensörün ortam analizini yapma.
    //
    // Veri arızası zaten ayrı Telegram hattından bildiriliyor.
    if (
        zone.valid !== true
    ) {

        analyzedZones[zoneKey] = {

            available:
                false,

            environmentState:
                "unavailable",

        };


        continue;

    }


    const zoneState =
        getZoneState(
            zoneKey
        );


    const previousState =
        zoneState.environmentState;


    const calculated =
        calculateCurrentState(
            zone
        );


    let newState =
        calculated.state;



    // ========================================================
    // 13. HYSTERESIS
    // ========================================================

    if (
        previousState ===
        "critical" &&
        newState !==
        "critical"
    ) {

        if (!safeFromCritical(zone)) {

            newState =
                "critical";

        }

    }


    if (
        previousState ===
        "warning" &&
        newState ===
        "normal"
    ) {

        if (!safeFromWarning(zone)) {

            newState =
                "warning";

        }

    }



    // ========================================================
    // 14. STATE CHANGE / REPEAT
    // ========================================================

    let shouldNotify =
        false;


    let notificationType =
        null;


    // NORMAL → WARNING
    if (
        newState === "warning" &&
        (
            previousState === "normal" ||
            previousState === "unknown"
        )
    ) {

        shouldNotify =
            true;

        notificationType =
            "environment_warning";

        zoneState.lastWarningAt =
            nowMs;

    }


    // NORMAL/WARNING → CRITICAL
    else if (
        newState === "critical" &&
        previousState !== "critical"
    ) {

        shouldNotify =
            true;

        notificationType =
            "environment_critical";

        zoneState.lastCriticalAt =
            nowMs;

    }


    // CRITICAL → WARNING
    else if (
        previousState === "critical" &&
        newState === "warning"
    ) {

        shouldNotify =
            true;

        notificationType =
            "environment_improved";

    }


    // WARNING/CRITICAL → NORMAL
    else if (
        newState === "normal" &&
        (
            previousState === "warning" ||
            previousState === "critical"
        ) &&
        CONFIG.alerts
            .sendEnvironmentRecovery
    ) {

        shouldNotify =
            true;

        notificationType =
            "environment_recovery";

        zoneState.lastRecoveryAt =
            nowMs;

    }


    // WARNING devam ediyor.
    else if (
        newState === "warning" &&
        previousState === "warning"
    ) {

        const repeatMs =
            CONFIG.alerts
                .warningRepeatMinutes *
            60 *
            1000;


        if (
            nowMs -
            zoneState.lastEnvironmentAlertAt >=
            repeatMs
        ) {

            shouldNotify =
                true;

            notificationType =
                "environment_warning_repeat";

        }

    }


    // CRITICAL devam ediyor.
    else if (
        newState === "critical" &&
        previousState === "critical"
    ) {

        const repeatMs =
            CONFIG.alerts
                .criticalRepeatMinutes *
            60 *
            1000;


        if (
            nowMs -
            zoneState.lastEnvironmentAlertAt >=
            repeatMs
        ) {

            shouldNotify =
                true;

            notificationType =
                "environment_critical_repeat";

        }

    }



    // ========================================================
    // 15. SON 1 SAATLİK KRİTİK OLAY
    // ========================================================

    const historicalCriticalReasons =
        getHistoricalCriticalReasons(
            zone
        );


    const historyRecord =
        zone.lastHour
            ?.recordIndex ??
        null;


    const newHistoryCritical =
        (
            historicalCriticalReasons.length > 0
            &&
            historyRecord !== null
            &&
            historyRecord !==
                zoneState.lastHistoryAlertRecord
        );


    // Anlık durum critical değil ama son saatte kritik değer
    // görülmüşse ayrıca bir kez bildir.
    if (
        newHistoryCritical &&
        newState !== "critical"
    ) {

        notifications.push({

            type:
                "recent_critical_history",

            severity:
                "critical",

            zoneKey,

            zoneName:
                zone.zoneName,

            message:
`🕘 <b>${zone.zoneName.toUpperCase()} — SON 1 SAATTE KRİTİK DEĞER</b>

Şu anki ortam kritik seviyede olmayabilir; ancak sensörün son saat kaydında çalışma sınırı dışında değer tespit edildi.

${historicalCriticalReasons
    .map(x => "❗ " + x)
    .join("\
")}

🌡 <b>Şu an:</b> ${formatNumber(zone.current.temperatureC)} °C
💧 <b>Nem:</b> %${formatNumber(zone.current.humidityPercent, 0)}

${createLastHourText(zone)}

🕒 <b>Kontrol:</b> ${formatLocalDateTime()}`,

        });


        zoneState.lastHistoryAlertRecord =
            historyRecord;

    }



    // ========================================================
    // 16. ORTAM TELEGRAM MESAJI
    // ========================================================

    if (shouldNotify) {

        zoneState.lastEnvironmentAlertAt =
            nowMs;


        const reasons =
            newState === "critical"

                ? calculated
                    .criticalReasons

                : calculated
                    .warningReasons;


        const limiting =
            zone.limits
                ?.limitingEquipment;


        let title =
            "";


        let footer =
            "";


        if (
            notificationType ===
            "environment_critical" ||
            notificationType ===
            "environment_critical_repeat"
        ) {

            title =
                `🚨 <b>${zone.zoneName.toUpperCase()} ORTAM KRİTİK ALARMI</b>`;

            footer =
                "🚨 <b>DURUM: KRİTİK</b>";

        }


        else if (
            notificationType ===
            "environment_warning" ||
            notificationType ===
            "environment_warning_repeat"
        ) {

            title =
                `⚠️ <b>${zone.zoneName.toUpperCase()} ORTAM ÖN UYARISI</b>`;

            footer =
                "⚠️ <b>DURUM: UYARI</b>";

        }


        else if (
            notificationType ===
            "environment_improved"
        ) {

            title =
                `🟡 <b>${zone.zoneName.toUpperCase()} ORTAM DURUMU İYİLEŞİYOR</b>`;

            footer =
                "🟡 Kritik seviyeden uyarı seviyesine geriledi.";

        }


        else {

            title =
                `✅ <b>${zone.zoneName.toUpperCase()} ORTAMI NORMALE DÖNDÜ</b>`;

            footer =
                "✅ <b>DURUM: NORMAL</b>";

        }


        notifications.push({

            type:
                notificationType,

            severity:
                newState,

            zoneKey,

            zoneName:
                zone.zoneName,

            message:
`${title}

${reasons.length
    ? reasons.map(x => "• " + x).join("\
")
    : "Değerler güvenli aralığa geri döndü."}

🌡 <b>Şu an:</b> ${formatNumber(zone.current.temperatureC)} °C
💧 <b>Nem:</b> %${formatNumber(zone.current.humidityPercent, 0)}

${createLastHourText(zone)}

🌫 <b>Çiğ noktası:</b> ${formatNumber(zone.dewPoint?.temperatureC, 2)} °C
↔️ <b>Çiğ noktası farkı:</b> ${formatNumber(zone.dewPoint?.spreadC, 2)} °C
💨 <b>Yoğuşma riski:</b> ${zone.dewPoint?.risk ?? "Bilinmiyor"}

📶 <b>BLE RSSI:</b> ${formatNumber(zone.sensorHealth?.rssiDbm, 0)} dBm
🔋 <b>Sensör pili:</b> ${formatNumber(zone.sensorHealth?.batteryVoltage, 3)} V

📋 <b>Tanımlanan kritik ortam aralığı</b>
🌡 ${zone.limits.critical.temperature.min} – ${zone.limits.critical.temperature.max} °C
💧 %${zone.limits.critical.humidity.min} – %${zone.limits.critical.humidity.max}

⚙️ <b>Üst sıcaklık limitini belirleyen ekipman:</b>
${joinEquipment(limiting?.temperatureMax)}

🕒 ${formatLocalDateTime()}

${footer}`,

        });

    }



    // ========================================================
    // 17. RSSI SAĞLIĞI — AYRI ALARM SINIFI
    // ========================================================

    const signalState =
        zone.sensorHealth?.signal ??
        "unknown";


    if (
        (
            signalState === "warning" ||
            signalState === "critical"
        )
        &&
        signalState !==
            zoneState.signalState
    ) {

        notifications.push({

            type:
                "sensor_signal_warning",

            severity:
                signalState,

            zoneKey,

            zoneName:
                zone.zoneName,

            message:
`📡 <b>${zone.zoneName.toUpperCase()} SENSÖR SİNYAL UYARISI</b>

LYWSD03MMC Bluetooth sinyal seviyesi zayıfladı.

📶 <b>RSSI:</b> ${formatNumber(zone.sensorHealth.rssiDbm, 0)} dBm
📊 <b>Seviye:</b> ${signalState}

Bu uyarı ortam sıcaklığı/nem alarmından bağımsızdır.

Sensör ile Raspberry Pi arasındaki mesafe veya engeller kontrol edilebilir.`,

        });

    }


    else if (
        signalState === "normal" &&
        (
            zoneState.signalState === "warning" ||
            zoneState.signalState === "critical"
        )
    ) {

        notifications.push({

            type:
                "sensor_signal_recovery",

            severity:
                "normal",

            zoneKey,

            zoneName:
                zone.zoneName,

            message:
`📶 <b>${zone.zoneName.toUpperCase()} SENSÖR SİNYALİ DÜZELDİ</b>

BLE sinyali tekrar normal seviyeye döndü.

RSSI: ${formatNumber(zone.sensorHealth.rssiDbm, 0)} dBm`,

        });

    }


    zoneState.signalState =
        signalState;


    zoneState.environmentState =
        newState;



    // ========================================================
    // 18. ANALİZ SONUCUNU SAKLA
    // ========================================================

    analyzedZones[zoneKey] = {

        available:
            true,

        previousState,

        environmentState:
            newState,

        temperatureC:
            zone.current.temperatureC,

        humidityPercent:
            zone.current.humidityPercent,

        dewPointC:
            zone.dewPoint?.temperatureC,

        dewPointSpreadC:
            zone.dewPoint?.spreadC,

        condensationRisk:
            zone.dewPoint?.risk,

        signalState,

        historicalCriticalReasons,

    };

}



// ============================================================
// 19. GÜNLÜK SAĞLIK RAPORU
// ============================================================

const todayKey =
    getTodayKey();


if (
    snapshot.schedule
        ?.isDailyReportTime === true
    &&
    CONFIG.alerts
        .sendDailyHealthReport === true
    &&
    persistent.lastDailyReportDate !==
        todayKey
) {

    const lines =
        [];


    for (
        const [
            zoneKey,
            zone
        ]
        of Object.entries(
            snapshot.zones ?? {}
        )
    ) {

        if (
            zone.valid !== true
        ) {

            lines.push(
`❌ <b>${zone.zoneName}</b>
Sensör verisi alınamıyor.`
            );

            continue;

        }


        const analyzed =
            analyzedZones[zoneKey];


        lines.push(
`✅ <b>${zone.zoneName}</b>
🌡 ${formatNumber(zone.current.temperatureC)} °C
💧 %${formatNumber(zone.current.humidityPercent, 0)}
🔥 1 sa. max: ${formatNumber(zone.lastHour?.temperatureMaxC)} °C
❄️ 1 sa. min: ${formatNumber(zone.lastHour?.temperatureMinC)} °C
🌫 Dew point: ${formatNumber(zone.dewPoint?.temperatureC, 2)} °C
📶 ${formatNumber(zone.sensorHealth?.rssiDbm, 0)} dBm
🔋 ${formatNumber(zone.sensorHealth?.batteryVoltage, 3)} V
📊 Durum: ${analyzed?.environmentState ?? "Bilinmiyor"}`
        );

    }


    notifications.push({

        type:
            "daily_health_report",

        severity:
            "info",

        zoneKey:
            null,

        zoneName:
            "Tüm Sistem",

        message:
`📋 <b>LORUV GÜNLÜK ORTAM SAĞLIK RAPORU</b>

${lines.join("\
\
")}

🕒 ${formatLocalDateTime()}

✅ Loruv Ortam İzleme Sistemi aktif.`,

    });


    persistent.lastDailyReportDate =
        todayKey;

}



// ============================================================
// 20. OUTPUT
// ============================================================

return [
    {
        json: {

            ...snapshot,


            environmentMonitoring: {

                shouldNotify:
                    notifications.length > 0,

                notificationCount:
                    notifications.length,

                notifications,

                analyzedZones,

            },

        },
    },
];

// ============================================================
// LORUV ORTAM İZLEME SİSTEMİ
// ORTAM BİLDİRİMLERİNİ AYIR
// ============================================================
//
// Ortam Güvenlik Alarm Motoru aynı çalışmada:
//
// - Ev sıcaklık alarmı
// - Çatı sıcaklık alarmı
// - RSSI uyarısı
// - Recovery
// - Son 1 saat kritik kayıt
// - Günlük sağlık raporu
//
// gibi birden fazla bildirim oluşturabilir.
//
// Her bildirimi ayrı n8n item'ına çeviriyoruz.
// Böylece Telegram node'u her mesajı ayrı gönderir.
// ============================================================


const inputItems =
    $input.all();


const outputItems =
    [];


for (const inputItem of inputItems) {

    const notifications =
        inputItem.json
            ?.environmentMonitoring
            ?.notifications;


    if (
        !Array.isArray(notifications) ||
        notifications.length === 0
    ) {

        continue;

    }


    for (const notification of notifications) {

        if (
            typeof notification?.message !== "string" ||
            notification.message.trim() === ""
        ) {

            continue;

        }


        outputItems.push({

            json: {

                message:
                    notification.message,

                type:
                    notification.type ?? "unknown",

                severity:
                    notification.severity ?? "unknown",

                zoneKey:
                    notification.zoneKey ?? null,

                zoneName:
                    notification.zoneName ?? null,

                source:
                    "environment_monitoring",

            },

        });

    }

}


return outputItems;

// ============================================================
// LORUV ORTAM İZLEME SİSTEMİ
// API ERİŞİM HATASINI SENSÖR VERİ HATASINA DÖNÜŞTÜR
// ============================================================
//
// Buraya yalnızca:
//
// 1. İlk HTTP denemeleri başarısız,
// 2. 70 saniye beklendi,
// 3. İkinci HTTP Request de kendi retry'larıyla başarısız
//
// olduğunda gelinir.
//
// Bu noktada Loruv Climate Bridge API'ye erişemediğimiz için
// Ev ve Çatı sensörlerinin ikisini de "veri alınamıyor"
// durumuna getiriyoruz.
//
// Sonraki mevcut:
//
// Nihai Sensör Durumu + Veri Alarmı
//
// node'umuz bu veriyi kullanarak Telegram alarmı oluşturacak.
// ============================================================



// ============================================================
// 1. MERKEZİ AYARLARI AL
// ============================================================

const controlPlan =
    $("Merkezi Ayarlar + Kontrol Planı")
        .first()
        .json;


const CONFIG =
    controlPlan.config;


// HTTP Request error output'undan gelen veri.
const errorInput =
    $json;



// ============================================================
// 2. HTTP HATA MESAJINI GÜVENLİ ŞEKİLDE BUL
// ============================================================

function getErrorMessage(input) {

    const candidates = [

        input?.error?.message,

        input?.error?.description,

        input?.error,

        input?.message,

        input?.description,

        input?.cause?.message,

    ];


    for (const candidate of candidates) {

        if (
            typeof candidate === "string" &&
            candidate.trim() !== ""
        ) {

            return candidate.trim();

        }

    }


    return "Loruv Climate Bridge API'ye ulaşılamadı.";

}


const errorMessage =
    getErrorMessage(
        errorInput
    );



// ============================================================
// 3. GEÇERSİZ BÖLGE OLUŞTUR
// ============================================================
//
// Nihai Sensör Durumu + Veri Alarmı node'unun beklediği
// veri yapısına uygun bir zone oluşturuyoruz.
// ============================================================

function createUnavailableZone(
    zoneKey,
    sensorConfig
) {

    return {

        zoneKey,

        zoneName:
            sensorConfig.name,

        deviceId:
            sensorConfig.deviceId,

        deviceName:
            sensorConfig.name,

        macAddress:
            null,

        found:
            false,

        valid:
            false,


        errors: [

            `${sensorConfig.name} sensör verisi alınamadı çünkü Loruv Climate Bridge API'ye erişilemedi.`,

            `API hatası: ${errorMessage}`,

        ],


        status:
            "api_unreachable",

        readAt:
            null,

        dataAgeMinutes:
            null,


        // ----------------------------------------------------
        // ANLIK VERİ
        // ----------------------------------------------------

        current: {

            temperatureC:
                null,

            humidityPercent:
                null,

        },


        // ----------------------------------------------------
        // SON 1 SAAT
        // ----------------------------------------------------

        lastHour: {

            available:
                false,

            recordIndex:
                null,

            temperatureMaxC:
                null,

            temperatureMinC:
                null,

            humidityMaxPercent:
                null,

            humidityMinPercent:
                null,

            timestampRaw:
                null,

            timestampIsoUtc:
                null,

        },


        // ----------------------------------------------------
        // OBSERVED
        // ----------------------------------------------------

        observed: {

            temperatureMaxC:
                null,

            temperatureMinC:
                null,

            humidityMaxPercent:
                null,

            humidityMinPercent:
                null,

        },


        // ----------------------------------------------------
        // DEW POINT
        // ----------------------------------------------------

        dewPoint: {

            temperatureC:
                null,

            spreadC:
                null,

            risk:
                "unknown",

            available:
                false,

        },


        // ----------------------------------------------------
        // SENSÖR SAĞLIĞI
        // ----------------------------------------------------

        sensorHealth: {

            rssiDbm:
                null,

            signal:
                "unknown",

            batteryVoltage:
                null,

            batteryReportedPercent:
                null,

            battery:
                "unknown",

        },


        // ----------------------------------------------------
        // BÖLGE LİMİTLERİ
        // ----------------------------------------------------

        limits:
            controlPlan
                .zoneLimits?.[zoneKey] ??
            null,

    };

}



// ============================================================
// 4. EV + ÇATI
// ============================================================

const home =
    createUnavailableZone(
        "home",
        CONFIG.sensors.home
    );


const attic =
    createUnavailableZone(
        "attic",
        CONFIG.sensors.attic
    );



// ============================================================
// 5. OUTPUT
// ============================================================

return [
    {
        json: {

            // HTTP transport seviyesinde başarısız.
            transportOk:
                false,


            api: {

                service:
                    "Loruv LYWSD03MMC BLE Climate Bridge API",

                apiVersion:
                    null,

                success:
                    false,

                cached:
                    null,

                cacheAgeSeconds:
                    null,

                capturedAt:
                    null,

                deviceCount:
                    0,

                globalErrors: [

                    "Loruv Climate Bridge API'ye erişilemedi.",

                    errorMessage,

                ],

            },


            // ------------------------------------------------
            // KONTROL PLANI
            // ------------------------------------------------

            schedule: {

                season:
                    controlPlan.season,

                priorityWindow:
                    controlPlan.priorityWindow,

                reason:
                    controlPlan.scheduleReason,

                description:
                    controlPlan.scheduleDescription,

                isDailyReportTime:
                    controlPlan.isDailyReportTime,

                localTime:
                    controlPlan.localTime,

            },


            // ------------------------------------------------
            // İKİ BÖLGE DE VERİ ALINAMAZ DURUMDA
            // ------------------------------------------------

            zones: {

                home,

                attic,

            },


            // ------------------------------------------------
            // VALIDATION
            // ------------------------------------------------

            validation: {

                allZonesValid:
                    false,

                atLeastOneZoneValid:
                    false,

                validZoneCount:
                    0,

                invalidZoneCount:
                    2,

            },


            // ------------------------------------------------
            // DEBUG / TEŞHİS
            // ------------------------------------------------

            transportError: {

                message:
                    errorMessage,

                raw:
                    errorInput,

            },

        },
    },
];
